            } else {
                if (Character.isDigit(normalizedToken.charAt(0)) && (normalizedToken.length() == 1 || Character.isDigit(normalizedToken.charAt(1)))) {
                    sb.append(normalizedToken);
                }
            }
        }
        return sb.toString();
