  buffer.setLength(0);

  for (int i = 0; i < word.length(); ++i) {
    c = word.charAt(i);
    ignore = false;
    for (int k = 0; k < ignoreChars.length(); ++k) {
      if (c == ignoreChars.charAt(k)) {
        ignore = true;
        break;
