	public long getCacheMisses() {
		return cacheMisses;
	}

	// efficacité en pourcentage du cache par rapport au total des accès
	public int getHitsRatio() {
		final long accessCount = cacheHits + cacheMisses;
		if (accessCount == 0) {
			return -1;
		}
		return (int) (100 * cacheHits / accessCount);
