	private static void extractGetPid(File tempFile) throws IOException {
		try (InputStream input = PID.class
				.getResourceAsStream("/net/bull/javamelody/resource/getpids.exe")) {
			InputOutput.pumpToFile(input, tempFile);
		}
	}
}

